                        w.backpatchLength4(at: elemLenPos)
                    } else {
                        let elemLenPos = w.reserveLength2()
                        elem.encodeOmniBufBodyFast(into: &w, deterministic: deterministic)
                        w.backpatchLength2(at: elemLenPos)
                    }
                }
                w.backpatchLength4(at: lenPos)
            } else {
                let lenPos = w.reserveLength2()
                w.appendByte(WireType.wireSubMsg)
                w.appendVarint(UInt64(self.neighbors.count))
                for elem in self.neighbors {
                    let elemLenPos = w.reserveLength2()
                    elem.encodeOmniBufBodyFast(into: &w, deterministic: deterministic)
                    w.backpatchLength2(at: elemLenPos)
                }
                w.backpatchLength2(at: lenPos)
            }
        }
        if self.sequence != 0 {
            w.appendTag(fieldNumber: 11, wireType: WireType.wireUint)
            w.appendVarint(self.sequence)
        }
    }

    @inlinable
    public mutating func mergeOmniBuf(from data: UnsafeBufferPointer<UInt8>, depth: Int, budget: inout DecodeBudget) throws {
        guard depth <= budget.maxDepth else {
            throw OmniBufError.depthLimitExceeded(depth)
        }
        var r = OmniBufReader(data)
        while !r.isAtEnd {
            let (fnum, wt) = try r.readTag()
            switch fnum {
            case 0:
                guard wt == WireType.wireSubMsg else {
                    throw OmniBufError.parse("Field #0 must have WireSubMsg (12), got \(wt)")
                }
                let slice = try r.readLenSlice()
                _ = try SchemaMeta.validateSlice(slice, depth: depth &+ 1, maxDepth: budget.maxDepth)
            case 1:
                guard wt == WireType.wireUint else {
                    try r.validateValue(wireType: wt, inCollection: false, depth: depth, maxDepth: budget.maxDepth)
                    continue
                }
                let val = UInt32(truncatingIfNeeded: try r.readVarint())
                self.asn = val
            case 2:
                guard wt == WireType.wireString else {
                    try r.validateValue(wireType: wt, inCollection: false, depth: depth, maxDepth: budget.maxDepth)
                    continue
                }
                let val = try r.readString()
                try budget.addAlloc(val.utf8.count)
                self.routerId = val
            case 3:
                if wt == WireType.wireBoolFalse {
                    self.active = false
                } else if wt == WireType.wireBoolTrue {
                    self.active = true
                } else {
                    try r.validateValue(wireType: wt, inCollection: false, depth: depth, maxDepth: budget.maxDepth)
                }
            case 4:
                guard wt == WireType.wireUint else {
                    try r.validateValue(wireType: wt, inCollection: false, depth: depth, maxDepth: budget.maxDepth)
                    continue
                }
                let val = try r.readVarint()
                self.uptimeSec = val
            case 5:
                guard wt == WireType.wireSint else {
                    try r.validateValue(wireType: wt, inCollection: false, depth: depth, maxDepth: budget.maxDepth)
                    continue
                }
                let val = try r.readSint32()
                self.rssiDbm = val
            case 6:
                guard wt == WireType.wireFloat64 else {
                    try r.validateValue(wireType: wt, inCollection: false, depth: depth, maxDepth: budget.maxDepth)
                    continue
                }
                let val = try r.readFloat64()
                self.cpuLoad = val
            case 7:
                guard wt == WireType.wireArray else {
                    try r.validateValue(wireType: wt, inCollection: false, depth: depth, maxDepth: budget.maxDepth)
                    continue
                }
                let arrDepth = depth &+ 1
                guard arrDepth <= budget.maxDepth else { throw OmniBufError.depthLimitExceeded(arrDepth) }
                let body = try r.readLenSlice(minLen: 2)
                let (elemWT, count, er0) = try OmniBufReader.parseArrayBody(body)
                guard elemWT == WireType.wireString else {
                    throw OmniBufError.parse("field 7 array element type mismatch")
                }
                try budget.addElements(count)
                try budget.addAlloc(count: count, elementBytes: max(MemoryLayout<String>.stride, 1))
                let (newCap, capOverflow) = self.tags.count.addingReportingOverflow(count)
                if capOverflow { throw OmniBufError.allocationLimitExceeded("array capacity overflow") }
                var er = er0
                self.tags.reserveCapacity(newCap)
                for _ in 0..<count {
                    let elem = try er.readString()
                    try budget.addAlloc(elem.utf8.count)
                    self.tags.append(elem)
                }
                guard er.isAtEnd else { throw OmniBufError.parse("WireArray trailing bytes") }
            case 8:
                guard wt == WireType.wireArray else {
                    try r.validateValue(wireType: wt, inCollection: false, depth: depth, maxDepth: budget.maxDepth)
                    continue
                }
                let arrDepth = depth &+ 1
                guard arrDepth <= budget.maxDepth else { throw OmniBufError.depthLimitExceeded(arrDepth) }
                let body = try r.readLenSlice(minLen: 2)
                let (elemWT, count, er0) = try OmniBufReader.parseArrayBody(body)
                guard elemWT == WireType.wireUint else {
                    throw OmniBufError.parse("field 8 array element type mismatch")
                }
                try budget.addElements(count)
                try budget.addAlloc(count: count, elementBytes: max(MemoryLayout<UInt32>.stride, 1))
                let (newCap, capOverflow) = self.prefixes.count.addingReportingOverflow(count)
                if capOverflow { throw OmniBufError.allocationLimitExceeded("array capacity overflow") }
                var er = er0
                self.prefixes.reserveCapacity(newCap)
                for _ in 0..<count {
                    let elem = UInt32(truncatingIfNeeded: try er.readVarint())
                    self.prefixes.append(elem)
                }
                guard er.isAtEnd else { throw OmniBufError.parse("WireArray trailing bytes") }
            case 9:
                guard wt == WireType.wireSubMsg else {
                    try r.validateValue(wireType: wt, inCollection: false, depth: depth, maxDepth: budget.maxDepth)
                    continue
                }
                let nextDepth = depth &+ 1
                guard nextDepth <= budget.maxDepth else { throw OmniBufError.depthLimitExceeded(nextDepth) }
                let slice = try r.readLenSlice()
                var sub = self.location ?? Location()
                try sub.mergeOmniBuf(from: slice, depth: nextDepth, budget: &budget)
                self.location = sub
            case 10:
                guard wt == WireType.wireArray else {
                    try r.validateValue(wireType: wt, inCollection: false, depth: depth, maxDepth: budget.maxDepth)
                    continue
                }
                let arrDepth = depth &+ 1
                guard arrDepth <= budget.maxDepth else { throw OmniBufError.depthLimitExceeded(arrDepth) }
                let body = try r.readLenSlice(minLen: 2)
                let (elemWT, count, er0) = try OmniBufReader.parseArrayBody(body)
                guard elemWT == WireType.wireSubMsg else {
                    throw OmniBufError.parse("field 10 array element type mismatch")
                }
                try budget.addElements(count)
                try budget.addAlloc(count: count, elementBytes: max(MemoryLayout<Neighbor>.stride, 16))
                let (newCap, capOverflow) = self.neighbors.count.addingReportingOverflow(count)
                if capOverflow { throw OmniBufError.allocationLimitExceeded("array capacity overflow") }
                var er = er0
                self.neighbors.reserveCapacity(newCap)
                for _ in 0..<count {
                    let elemDepth = arrDepth &+ 1
                    guard elemDepth <= budget.maxDepth else { throw OmniBufError.depthLimitExceeded(elemDepth) }
                    let slice = try er.readLenSlice()
                    var elem = Neighbor()
                    try elem.mergeOmniBuf(from: slice, depth: elemDepth, budget: &budget)
                    self.neighbors.append(elem)
                }
                guard er.isAtEnd else { throw OmniBufError.parse("WireArray trailing bytes") }
            case 11:
                guard wt == WireType.wireUint else {
                    try r.validateValue(wireType: wt, inCollection: false, depth: depth, maxDepth: budget.maxDepth)
                    continue
                }
                let val = try r.readVarint()
                self.sequence = val
            default:
                try r.validateValue(wireType: wt, inCollection: false, depth: depth, maxDepth: budget.maxDepth)
            }
        }
    }

    public static var omniBufSchemaMeta: SchemaMeta {
        var visited: Set<String> = []
        return buildOmniBufSchemaMeta(visited: &visited)
    }

    public static func buildOmniBufSchemaMeta(visited: inout Set<String>) -> SchemaMeta {
        var fields: [UInt32: String] = [:]
        var children: [UInt32: SchemaMeta] = [:]
        let typeKey = "omnibuf.bench.PeerUpdate"
        let inserted = visited.insert(typeKey).inserted
        defer { if inserted { visited.remove(typeKey) } }
        fields[1] = "asn"
        fields[2] = "router_id"
        fields[3] = "active"
        fields[4] = "uptime_sec"
        fields[5] = "rssi_dbm"
        fields[6] = "cpu_load"
        fields[7] = "tags"
        fields[8] = "prefixes"
        fields[9] = "location"
        if inserted { children[9] = Location.buildOmniBufSchemaMeta(visited: &visited) }
        fields[10] = "neighbors"
        if inserted { children[10] = Neighbor.buildOmniBufSchemaMeta(visited: &visited) }
        fields[11] = "sequence"
        return SchemaMeta(typeName: "PeerUpdate", fields: fields, children: children)
    }
}

public struct OpaquePeerUpdate: Sendable {
    public let raw: [UInt8]
    public let offset: Int
    public let length: Int
    @usableFromInline internal var dirtyMask: UInt64 = 0
    @usableFromInline internal var dirty_asn: UInt32 = 0
    @usableFromInline internal var dirty_router_id: String = ""
    @usableFromInline internal var dirty_active: Bool = false
    @usableFromInline internal var dirty_uptime_sec: UInt64 = 0
    @usableFromInline internal var dirty_rssi_dbm: Int32 = 0
    @usableFromInline internal var dirty_cpu_load: Double = 0
    @usableFromInline internal var dirty_tags: [String] = []
    @usableFromInline internal var dirty_prefixes: [UInt32] = []
    @usableFromInline internal var dirty_location: Location? = nil
    @usableFromInline internal var dirty_neighbors: [Neighbor] = []
    @usableFromInline internal var dirty_sequence: UInt64 = 0

    @inlinable
    public init(_ raw: [UInt8]) {
        self.raw = raw
        self.offset = 0
        self.length = raw.count
    }

    @inlinable
    public init(raw: [UInt8], offset: Int, length: Int) {
        precondition(offset >= 0 && length >= 0 && offset <= raw.count && length <= raw.count - offset, "OpaquePeerUpdate slice out of bounds")
        self.raw = raw
        self.offset = offset
        self.length = length
    }

    @inlinable
    @inline(__always)
    internal func withSlice<R>(_ body: (UnsafeBufferPointer<UInt8>) -> R) -> R {
        raw.withUnsafeBufferPointer { buf in
            body(UnsafeBufferPointer(start: buf.baseAddress?.advanced(by: offset), count: length))
        }
    }

    @inlinable
    public func getAsn() -> UInt32 {
        if (dirtyMask & (1 &<< 1)) != 0 { return dirty_asn }
        return withSlice { OpaqueWire.readUint32(in: $0, fieldNumber: 1) }
    }
    @inlinable
    public mutating func setAsn(_ value: UInt32) {
        dirty_asn = value
        dirtyMask |= (1 &<< 1)
    }
    @inlinable
    public func getRouterId() -> String {
        if (dirtyMask & (1 &<< 2)) != 0 { return dirty_router_id }
        return withSlice { OpaqueWire.readString(in: $0, fieldNumber: 2) }
    }
    @inlinable
    public mutating func setRouterId(_ value: String) {
        dirty_router_id = value
        dirtyMask |= (1 &<< 2)
    }
    @inlinable
    public func getActive() -> Bool {
        if (dirtyMask & (1 &<< 3)) != 0 { return dirty_active }
        return withSlice { OpaqueWire.readBool(in: $0, fieldNumber: 3) }
    }
    @inlinable
    public mutating func setActive(_ value: Bool) {
        dirty_active = value
        dirtyMask |= (1 &<< 3)
    }
    @inlinable
    public func getUptimeSec() -> UInt64 {
        if (dirtyMask & (1 &<< 4)) != 0 { return dirty_uptime_sec }
        return withSlice { OpaqueWire.readUint64(in: $0, fieldNumber: 4) }
    }
    @inlinable
    public mutating func setUptimeSec(_ value: UInt64) {
        dirty_uptime_sec = value
        dirtyMask |= (1 &<< 4)
    }
    @inlinable
    public func getRssiDbm() -> Int32 {
        if (dirtyMask & (1 &<< 5)) != 0 { return dirty_rssi_dbm }
        return withSlice { OpaqueWire.readSint32(in: $0, fieldNumber: 5) }
    }
    @inlinable
    public mutating func setRssiDbm(_ value: Int32) {
        dirty_rssi_dbm = value
        dirtyMask |= (1 &<< 5)
    }
    @inlinable
    public func getCpuLoad() -> Double {
        if (dirtyMask & (1 &<< 6)) != 0 { return dirty_cpu_load }
        return withSlice { OpaqueWire.readFloat64(in: $0, fieldNumber: 6) }
    }
    @inlinable
    public mutating func setCpuLoad(_ value: Double) {
        dirty_cpu_load = value
        dirtyMask |= (1 &<< 6)
    }
    @inlinable
    public var tagsCount: Int {
        if (dirtyMask & (1 &<< 7)) != 0 { return dirty_tags.count }
        return withSlice { OpaqueWire.arrayCount(in: $0, fieldNumber: 7, expectedElemType: WireType.wireString) }
    }
    @inlinable
    public mutating func setTags(_ value: [String]) {
        dirty_tags = value
        dirtyMask |= (1 &<< 7)
    }
    @inlinable
    public var prefixesCount: Int {
        if (dirtyMask & (1 &<< 8)) != 0 { return dirty_prefixes.count }
        return withSlice { OpaqueWire.arrayCount(in: $0, fieldNumber: 8, expectedElemType: WireType.wireUint) }
    }
    @inlinable
    public mutating func setPrefixes(_ value: [UInt32]) {
        dirty_prefixes = value
        dirtyMask |= (1 &<< 8)
    }
    @inlinable
    public func getLocation() -> OpaqueLocation {
        if (dirtyMask & (1 &<< 9)) != 0 {
            return OpaqueLocation(dirty_location?.marshalOmniBuf() ?? [])
        }
        return withSlice { slice in
            guard let loc = OpaqueWire.locateSubMsgRange(in: slice, fieldNumber: 9) else {
                return OpaqueLocation(raw: [], offset: 0, length: 0)
            }
            if !loc.multiple {
                return OpaqueLocation(raw: raw, offset: offset &+ loc.start, length: loc.end &- loc.start)
            }
            return OpaqueLocation(OpaqueWire.readMergedSubMsgBytes(in: slice, fieldNumber: 9))
        }
    }
    @inlinable
    public mutating func setLocation(_ value: Location?) {
        dirty_location = value
        dirtyMask |= (1 &<< 9)
    }
    @inlinable
    public var neighborsCount: Int {
        if (dirtyMask & (1 &<< 10)) != 0 { return dirty_neighbors.count }
        return withSlice { OpaqueWire.arrayCount(in: $0, fieldNumber: 10, expectedElemType: WireType.wireSubMsg) }
    }
    @inlinable
    public mutating func setNeighbors(_ value: [Neighbor]) {
        dirty_neighbors = value
        dirtyMask |= (1 &<< 10)
    }
    @inlinable
    public func getSequence() -> UInt64 {
        if (dirtyMask & (1 &<< 11)) != 0 { return dirty_sequence }
        return withSlice { OpaqueWire.readUint64(in: $0, fieldNumber: 11) }
    }
    @inlinable
    public mutating func setSequence(_ value: UInt64) {
        dirty_sequence = value
        dirtyMask |= (1 &<< 11)
    }

    @inlinable
    internal func appendDirtyField(_ fnum: UInt32, into w: inout OmniBufWriter) {
        let deterministic = true
        _ = deterministic
        switch fnum {
        case 1:
            if self.dirty_asn != 0 {
                w.appendTag(fieldNumber: 1, wireType: WireType.wireUint)
                w.appendVarint(UInt64(self.dirty_asn))
            }
        case 2:
            if !self.dirty_router_id.isEmpty {
                w.appendTag(fieldNumber: 2, wireType: WireType.wireString)
                w.appendStringValue(self.dirty_router_id)
            }
        case 3:
            if self.dirty_active {
                w.appendTag(fieldNumber: 3, wireType: WireType.wireBoolTrue)
            }
        case 4:
            if self.dirty_uptime_sec != 0 {
                w.appendTag(fieldNumber: 4, wireType: WireType.wireUint)
                w.appendVarint(self.dirty_uptime_sec)
            }
        case 5:
            if self.dirty_rssi_dbm != 0 {
                w.appendTag(fieldNumber: 5, wireType: WireType.wireSint)
                w.appendZigZag32(self.dirty_rssi_dbm)
            }
        case 6:
            if self.dirty_cpu_load.bitPattern != 0 {
                w.appendTag(fieldNumber: 6, wireType: WireType.wireFloat64)
                w.appendFloat64(self.dirty_cpu_load)
            }
        case 7:
            if !self.dirty_tags.isEmpty {
                w.appendTag(fieldNumber: 7, wireType: WireType.wireArray)
                let lenPos = w.reserveLength2()
                w.appendByte(WireType.wireString)
                w.appendVarint(UInt64(self.dirty_tags.count))
                for elem in self.dirty_tags {
                    w.appendStringValue(elem)
                }
                w.backpatchLength2(at: lenPos)
            }
        case 8:
            if !self.dirty_prefixes.isEmpty {
                w.appendTag(fieldNumber: 8, wireType: WireType.wireArray)
                let lenPos = w.reserveLength2()
                w.appendByte(WireType.wireUint)
                w.appendVarint(UInt64(self.dirty_prefixes.count))
                for elem in self.dirty_prefixes {
                    w.appendVarint(UInt64(elem))
                }
                w.backpatchLength2(at: lenPos)
            }
        case 9:
            if let sub = self.dirty_location {
                w.appendTag(fieldNumber: 9, wireType: WireType.wireSubMsg)
                if sub.estimatedOmniBufSize > 16_383 {
                    let lenPos = w.reserveLength4()
                    sub.encodeOmniBufBodyFast(into: &w, deterministic: deterministic)
                    w.backpatchLength4(at: lenPos)
                } else {
                    let lenPos = w.reserveLength2()
                    sub.encodeOmniBufBodyFast(into: &w, deterministic: deterministic)
                    w.backpatchLength2(at: lenPos)
                }
            }
        case 10:
            if !self.dirty_neighbors.isEmpty {
                w.appendTag(fieldNumber: 10, wireType: WireType.wireArray)
                var arrEst = 8
                for elem in self.dirty_neighbors { arrEst &+= elem.estimatedOmniBufSize &+ 4 }
                if arrEst > 16_383 {
                    let lenPos = w.reserveLength4()
                    w.appendByte(WireType.wireSubMsg)
                    w.appendVarint(UInt64(self.dirty_neighbors.count))
                    for elem in self.dirty_neighbors {
                        if elem.estimatedOmniBufSize > 16_383 {
                            let elemLenPos = w.reserveLength4()
                            elem.encodeOmniBufBodyFast(into: &w, deterministic: deterministic)
                            w.backpatchLength4(at: elemLenPos)
                        } else {
                            let elemLenPos = w.reserveLength2()
                            elem.encodeOmniBufBodyFast(into: &w, deterministic: deterministic)
                            w.backpatchLength2(at: elemLenPos)
                        }
                    }
                    w.backpatchLength4(at: lenPos)
                } else {
                    let lenPos = w.reserveLength2()
                    w.appendByte(WireType.wireSubMsg)
                    w.appendVarint(UInt64(self.dirty_neighbors.count))
                    for elem in self.dirty_neighbors {
                        let elemLenPos = w.reserveLength2()
                        elem.encodeOmniBufBodyFast(into: &w, deterministic: deterministic)
                        w.backpatchLength2(at: elemLenPos)
                    }
                    w.backpatchLength2(at: lenPos)
                }
            }
        case 11:
            if self.dirty_sequence != 0 {
                w.appendTag(fieldNumber: 11, wireType: WireType.wireUint)
                w.appendVarint(self.dirty_sequence)
            }
        default:
            break
        }
    }

    @inlinable
    public func marshal() -> [UInt8] {
        if dirtyMask == 0 {
            if offset == 0 && length == raw.count { return raw }
            return Array(raw[offset..<(offset + length)])
        }
        var dst: [UInt8] = []
        OpaqueWire.spliceFields(into: &dst, raw: raw, offset: offset, length: length, dirtyMask: dirtyMask, maxField: 11) { w, fnum in
            self.appendDirtyField(fnum, into: &w)
        }
        return dst
    }

    @inlinable
    public func tryMarshal() throws -> [UInt8] {
        var dst: [UInt8] = []
        try OpaqueWire.trySpliceFields(into: &dst, raw: raw, offset: offset, length: length, dirtyMask: dirtyMask, maxField: 11) { w, fnum in
            self.appendDirtyField(fnum, into: &w)
        }
        return dst
    }
}

